-- CoLearn: Supabase-native application schema. Auth credentials stay in auth.users.
create schema if not exists app;
revoke all on schema app from public;
grant usage on schema app to authenticated, anon;
create table public.profiles (
 id uuid primary key references auth.users on delete cascade, legacy_id bigint unique,
 username text not null unique check(username ~ '^[A-Za-z0-9_.-]{3,150}$'), full_name text not null default '',
 avatar text, bio text not null default '', headline text not null default '', role text not null default 'learner' check(role in ('learner','builder','mentor','admin')),
 location text not null default '', github text not null default '', linkedin text not null default '', website text not null default '', availability text not null default '', interests jsonb not null default '[]',
 xp integer not null default 0 check(xp>=0), level integer not null default 1, streak_days integer not null default 0, last_active timestamptz,
 is_verified boolean not null default false, onboarding_completed boolean not null default false, is_active boolean not null default true, is_staff boolean not null default false, is_superuser boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create unique index profiles_username_ci on public.profiles(lower(username));
create table public.skills(id bigint generated by default as identity primary key,slug text unique not null,name text unique not null,category text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_skills(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,skill_id bigint not null references public.skills on delete cascade,level text not null default 'beginner' check(level in ('beginner','intermediate','advanced')),is_verified boolean not null default false,unique(user_id,skill_id));
create table public.connections(id bigint generated by default as identity primary key,from_user_id uuid not null references public.profiles on delete cascade,to_user_id uuid not null references public.profiles on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','blocked')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(from_user_id<>to_user_id));
create unique index connections_pair on public.connections(least(from_user_id,to_user_id),greatest(from_user_id,to_user_id));
create table public.books(id bigint generated by default as identity primary key,slug text unique not null,title text not null,author text not null,description text not null default '',cover text,category text not null default '',difficulty text not null default 'beginner' check(difficulty in ('beginner','intermediate','advanced')),tags jsonb not null default '[]',est_minutes integer not null default 0,total_pages integer not null default 0,published_at timestamptz,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.chapters(id bigint generated by default as identity primary key,book_id bigint not null references public.books on delete cascade,slug text unique not null,title text not null,chapter_number integer not null check(chapter_number>0),content text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(book_id,chapter_number));
create table public.reading_progress(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,book_id bigint not null references public.books on delete cascade,chapter_id bigint references public.chapters on delete set null,progress_percent integer not null default 0 check(progress_percent between 0 and 100),completed boolean not null default false,completed_chapters bigint[] not null default '{}',book_completion_awarded boolean not null default false,last_read_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,book_id));
create table public.bookmarks(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,book_id bigint not null references public.books on delete cascade,chapter_id bigint not null references public.chapters on delete cascade,page integer not null default 1,note text not null default '',created_at timestamptz not null default now(),unique(user_id,chapter_id));
create table public.notes(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,chapter_id bigint not null references public.chapters on delete cascade,content text not null check(length(content) between 1 and 5000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.projects(id bigint generated by default as identity primary key,slug text unique not null,owner_id uuid not null references public.profiles on delete cascade,title text not null check(length(title) between 3 and 200),summary text not null default '',description text not null default '',category text not null default '',tech_stack jsonb not null default '[]',looking_for_roles jsonb not null default '[]',cover text,status text not null default 'idea' check(status in ('idea','active','completed','archived')),max_members integer not null default 5 check(max_members between 1 and 50),is_public boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_members(id bigint generated by default as identity primary key,project_id bigint not null references public.projects on delete cascade,user_id uuid not null references public.profiles on delete cascade,role text not null default 'member' check(role in ('owner','member','mentor')),joined_at timestamptz not null default now(),unique(project_id,user_id));
create unique index project_one_owner on public.project_members(project_id) where role='owner';
create table public.join_requests(id bigint generated by default as identity primary key,project_id bigint not null references public.projects on delete cascade,user_id uuid not null references public.profiles on delete cascade,message text not null default '',status text not null default 'pending' check(status in ('pending','invited','approved','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,user_id));
create table public.tasks(id bigint generated by default as identity primary key,project_id bigint not null references public.projects on delete cascade,assignee_id uuid references public.profiles on delete set null,title text not null check(length(title) between 1 and 200),description text not null default '',status text not null default 'todo' check(status in ('todo','in_progress','review','done')),priority text not null default 'medium' check(priority in ('low','medium','high','urgent')),due_date date,"order" integer not null default 0,xp_awarded boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.milestones(id bigint generated by default as identity primary key,project_id bigint not null references public.projects on delete cascade,title text not null,description text not null default '',due_date date,status text not null default 'planned' check(status in ('planned','in_progress','done')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_updates(id bigint generated by default as identity primary key,project_id bigint not null references public.projects on delete cascade,author_id uuid not null references public.profiles on delete cascade,body text not null check(length(body) between 1 and 5000),created_at timestamptz not null default now());
create table public.threads(id bigint generated by default as identity primary key,slug text unique not null,author_id uuid not null references public.profiles on delete cascade,title text not null check(length(title) between 3 and 200),body text not null check(length(body) between 1 and 20000),category text not null default 'community' check(category in ('frontend','backend','product','career','community')),is_pinned boolean not null default false,views integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tags(id bigint generated by default as identity primary key,slug text unique not null,name text unique not null,color text not null default '#2E78E5',created_at timestamptz not null default now());
create table public.thread_tags(thread_id bigint not null references public.threads on delete cascade,tag_id bigint not null references public.tags on delete cascade,primary key(thread_id,tag_id));
create table public.comments(id bigint generated by default as identity primary key,thread_id bigint not null references public.threads on delete cascade,author_id uuid not null references public.profiles on delete cascade,parent_id bigint references public.comments on delete cascade,body text not null check(length(body) between 1 and 5000),xp_awarded boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.votes(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,thread_id bigint references public.threads on delete cascade,comment_id bigint references public.comments on delete cascade,value smallint not null check(value in (-1,1)),created_at timestamptz not null default now(),check(num_nonnulls(thread_id,comment_id)=1),unique(user_id,thread_id),unique(user_id,comment_id));
create table public.thread_views(thread_id bigint not null references public.threads on delete cascade,user_id uuid not null references public.profiles on delete cascade,viewed_on date not null default current_date,primary key(thread_id,user_id,viewed_on));
create table public.reports(id bigint generated by default as identity primary key,reporter_id uuid not null references public.profiles on delete cascade,target_type text not null check(target_type in ('thread','comment','user')),thread_id bigint references public.threads on delete set null,comment_id bigint references public.comments on delete set null,target_user_id uuid references public.profiles on delete set null,reason text not null,status text not null default 'open' check(status in ('open','review','resolved','dismissed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(num_nonnulls(thread_id,comment_id,target_user_id)<=1));
create unique index reports_open_thread on public.reports(reporter_id,thread_id) where status in ('open','review');
create unique index reports_open_comment on public.reports(reporter_id,comment_id) where status in ('open','review');
create unique index reports_open_user on public.reports(reporter_id,target_user_id) where status in ('open','review');
create table public.contact_messages(id bigint generated by default as identity primary key,name text not null,email text not null,subject text not null,message text not null check(length(message) between 10 and 5000),is_resolved boolean not null default false,ip_hash text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.badges(id bigint generated by default as identity primary key,slug text unique not null,name text not null,description text not null default '',criteria_key text not null,xp_reward integer not null default 0,icon text not null default 'award',required integer not null default 1,category text not null default 'Other',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_badges(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,badge_id bigint not null references public.badges on delete cascade,earned_at timestamptz not null default now(),unique(user_id,badge_id));
create table public.xp_events(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,amount integer not null,reason text not null,source text not null default '',created_at timestamptz not null default now(),unique(user_id,reason,source));
create table public.notifications(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles on delete cascade,actor_id uuid references public.profiles on delete set null,verb text not null,target_type text,target_id bigint,target_label text not null default '',target_slug text not null default '',is_read boolean not null default false,created_at timestamptz not null default now());
create table app.policy_acceptances(user_id uuid primary key references auth.users on delete cascade,accepted_at timestamptz not null default now(),version text not null default '2026-09-19');
-- Index every referencing FK; RLS joins and cascades must not scan whole tables.
do $$ declare r record; begin for r in select c.relname table_name,a.attname column_name from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral unnest(k.conkey) x(attnum) join pg_attribute a on a.attrelid=c.oid and a.attnum=x.attnum where n.nspname='public' and k.contype='f' loop execute format('create index if not exists %I on public.%I(%I)',r.table_name||'_'||r.column_name||'_idx',r.table_name,r.column_name); end loop; end $$;
create index projects_tech on public.projects using gin(tech_stack);
create index books_tags on public.books using gin(tags);
create index notifications_unread on public.notifications(user_id,is_read,created_at desc);
create index xp_user_date on public.xp_events(user_id,created_at desc);
create index contact_rate on public.contact_messages(ip_hash,created_at desc);
create function app.touch() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now();return new;end $$;
do $$ declare r record;begin for r in select table_name from information_schema.columns where table_schema='public' and column_name='updated_at' loop execute format('create trigger touch before update on public.%I for each row execute function app.touch()',r.table_name);end loop;end $$;
create function app.active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_active) $$;
create function app.staff() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_active and is_staff) $$;
create function app.member(p bigint) returns boolean language sql stable security definer set search_path='' as $$ select app.active() and exists(select 1 from public.project_members where project_id=p and user_id=auth.uid()) $$;
create function app.owner(p bigint) returns boolean language sql stable security definer set search_path='' as $$ select app.active() and exists(select 1 from public.projects where id=p and owner_id=auth.uid()) $$;
create function app.visible(p bigint) returns boolean language sql stable security definer set search_path='' as $$ select app.staff() or (app.active() and exists(select 1 from public.projects where id=p and (is_public or owner_id=auth.uid() or app.member(p)))) $$;
-- Default deny. Privileged state is changed only through checked RPCs/triggers.
do $$ declare r record; begin for r in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',r.tablename);execute format('revoke all on public.%I from anon, authenticated',r.tablename);execute format('grant select on public.%I to authenticated',r.tablename);end loop;end $$;
grant usage,select on all sequences in schema public to authenticated;
grant select on public.profiles,public.user_skills,public.skills,public.badges,public.user_badges to anon;
create policy profiles_read on public.profiles for select using(is_active or id=auth.uid() or app.staff());
create policy skills_read on public.skills for select using(true);
create policy user_skills_read on public.user_skills for select using(true);
create policy badges_read on public.badges for select using(true);
create policy user_badges_read on public.user_badges for select using(true);
create policy profiles_edit on public.profiles for update to authenticated using(id=auth.uid() and app.active()) with check(id=auth.uid());
grant update(username,full_name,avatar,bio,headline,role,location,github,linkedin,website,availability,interests) on public.profiles to authenticated;
create policy books_read on public.books for select to authenticated using(app.active());
create policy chapters_read on public.chapters for select to authenticated using(app.active());
create policy projects_read on public.projects for select to authenticated using(app.visible(id));
create policy members_read on public.project_members for select to authenticated using(app.visible(project_id));
create policy tasks_read on public.tasks for select to authenticated using(app.member(project_id) or app.staff());
create policy milestones_read on public.milestones for select to authenticated using(app.visible(project_id));
create policy updates_read on public.project_updates for select to authenticated using(app.visible(project_id));
create policy requests_read on public.join_requests for select to authenticated using(app.active() and (user_id=auth.uid() or app.owner(project_id) or app.staff()));
create policy connections_read on public.connections for select to authenticated using(app.active() and (from_user_id=auth.uid() or to_user_id=auth.uid()));
do $$ declare t text;begin foreach t in array array['reading_progress','bookmarks','notes','xp_events','notifications'] loop execute format('create policy own_read on public.%I for select to authenticated using(user_id=auth.uid() and app.active())',t);end loop; foreach t in array array['threads','comments','tags','thread_tags'] loop execute format('create policy community_read on public.%I for select to authenticated using(app.active())',t);end loop;end $$;
create policy votes_read on public.votes for select to authenticated using(app.active());
create policy reports_read on public.reports for select to authenticated using(app.staff() or (app.active() and reporter_id=auth.uid()));
create policy contacts_staff on public.contact_messages for all to authenticated using(app.staff()) with check(app.staff());
grant update(is_read) on public.notifications to authenticated;
create policy notifications_update on public.notifications for update to authenticated using(user_id=auth.uid() and app.active()) with check(user_id=auth.uid());
-- Staff content operations and normal collaboration CRUD.
do $$ declare t text; begin foreach t in array array['books','chapters','tags','badges','skills'] loop execute format('grant insert,update,delete on public.%I to authenticated',t);execute format('create policy staff_write on public.%I for all to authenticated using(app.staff()) with check(app.staff())',t);end loop;end $$;
grant insert,delete on public.notes,public.project_updates to authenticated;
create policy notes_insert on public.notes for insert to authenticated with check(user_id=auth.uid() and app.active());
create policy notes_delete on public.notes for delete to authenticated using(user_id=auth.uid() and app.active());
create policy updates_insert on public.project_updates for insert to authenticated with check(author_id=auth.uid() and app.member(project_id));
create policy updates_delete on public.project_updates for delete to authenticated using(app.owner(project_id) or (app.active() and author_id=auth.uid()));
grant insert,delete on public.projects,public.tasks,public.milestones,public.threads,public.comments to authenticated;
grant update(title,summary,description,category,tech_stack,looking_for_roles,cover,status,max_members,is_public) on public.projects to authenticated;
grant update(title,description,status,priority,due_date,"order",assignee_id) on public.tasks to authenticated;
grant update(title,description,status,due_date) on public.milestones to authenticated;
grant update(title,body,category) on public.threads to authenticated;
grant update(body) on public.comments to authenticated;
create policy project_insert on public.projects for insert to authenticated with check(owner_id=auth.uid() and app.active());
create policy project_update on public.projects for update to authenticated using(app.owner(id) or app.staff()) with check(app.owner(id) or app.staff());
create policy project_delete on public.projects for delete to authenticated using(app.owner(id) or app.staff());
create policy tasks_write on public.tasks for all to authenticated using(app.member(project_id) or app.staff()) with check(app.member(project_id) or app.staff());
create policy milestones_write on public.milestones for all to authenticated using(app.owner(project_id) or app.staff()) with check(app.owner(project_id) or app.staff());
create policy threads_insert on public.threads for insert to authenticated with check(author_id=auth.uid() and app.active() and not is_pinned and views=0);
create policy threads_update on public.threads for update to authenticated using(app.active() and (author_id=auth.uid() or app.staff())) with check(app.active() and (author_id=auth.uid() or app.staff()));
create policy threads_delete on public.threads for delete to authenticated using(app.active() and (author_id=auth.uid() or app.staff()));
create policy comments_insert on public.comments for insert to authenticated with check(author_id=auth.uid() and app.active() and not xp_awarded);
create policy comments_update on public.comments for update to authenticated using(app.active() and (author_id=auth.uid() or app.staff()));
create policy comments_delete on public.comments for delete to authenticated using(app.active() and (author_id=auth.uid() or app.staff()));
revoke all on all functions in schema app from public;
grant execute on function app.active(),app.staff(),app.member(bigint),app.owner(bigint),app.visible(bigint) to authenticated,anon;
